
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_scan0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_scan0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.663391164362241e+00, -3.589223923392154e+00, -3.485266420061210e+00, -3.341192818457249e+00, -3.144731249107124e+00, -2.882946759582482e+00, -2.545333095546623e+00, -2.129390374678535e+00, -1.647995031990664e+00, -1.126833035883163e+00, -6.457594593171666e-01, -4.693470178817115e-01, -4.692763304280226e-01, -3.988066028714801e-01, -2.719934713738727e-01, -1.470657815192271e-01, -5.933863162123441e-02, -1.584549769844917e-02, -2.217598476994903e-03, -1.056336626726522e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


